'use client'
import { useRef } from 'react'
import { cn, useEffectPropSignal, useSignal, useSignalEffect, useSignals } from '@cascivo/core'
import styles from './streaming-text.module.css'

export interface StreamingTextProps {
  text: string
  /**
   * Characters revealed per animation frame.
   *
   * @defaultValue `2`
   * @see the component manifest
   */
  speed?: number
  onComplete?: () => void
  className?: string
}

export function StreamingText({ text, speed = 2, onComplete, className }: StreamingTextProps) {
  useSignals()
  const displayed = useSignal('')
  // The effect must re-run when `text` grows mid-stream; a plain prop read inside it is not
  // tracked, so it would stop at the first chunk.
  const targetSignal = useEffectPropSignal(text)
  const onCompleteRef = useRef(onComplete)
  onCompleteRef.current = onComplete

  // Reset when text prop changes
  displayed.value = displayed.value.length > text.length ? '' : displayed.value

  useSignalEffect(() => {
    const target = targetSignal.value
    if (displayed.value === target) {
      onCompleteRef.current?.()
      return
    }
    let rafId: number
    function tick() {
      const current = displayed.value
      if (current.length >= target.length) {
        onCompleteRef.current?.()
        return
      }
      displayed.value = target.slice(0, current.length + speed)
      rafId = requestAnimationFrame(tick)
    }
    rafId = requestAnimationFrame(tick)
    return () => cancelAnimationFrame(rafId)
  })

  return (
    <span className={cn(styles['root'], className)}>
      {displayed.value}
      {displayed.value !== text && <span className={styles['cursor']} aria-hidden="true" />}
    </span>
  )
}

@layer cascivo.component {
  .root {
    display: inline;
  }
  .cursor {
    display: inline-block;
    width: 2px;
    height: 1em;
    background: currentColor;
    margin-inline-start: 1px;
    vertical-align: text-bottom;
  }

  /* Decorative loop — opt-in, so a user who expresses no preference gets no motion. */
  @media (prefers-reduced-motion: no-preference) {
    .cursor {
      animation: global(cascivo-blink) var(--cascivo-duration-loop-fast) step-end infinite;
    }
  }
}
